// Free deletion site and two distinct crossing additions. Enumerate every 76-edge core with no red triangle or blue eight and degree <=7. Input one 27-graph and site per line. No restrictions on path count or sharing endpoints.
use std::io::{self,BufRead};type A=[u32;26];type E=(usize,usize);const F:u32=(1<<26)-1;
fn blue(a:&A,mut v:u32,k:u32)->bool{if k==0{return true}while v.count_ones()>=k{let j=v.trailing_zeros()as usize;v&=v-1;if blue(a,v&!a[j],k-1){return true}}false}
fn safe(a:&A,(i,j):E)->bool{!blue(a,F&!(a[i]|a[j]),6)}
fn rec(a:&mut A,p:&[E],need:usize,tag:(usize,E,E),ct:&mut u64){if p.len()<need{return}if need==0{if a.iter().any(|x|x.count_ones()>7){return}for i in 0..26{let mut v=a[i];while v!=0{let j=v.trailing_zeros()as usize;v&=v-1;if a[i]&a[j]!=0{return}}}*ct+=1;println!("core {} {} {} {} {} {:?}",tag.0,tag.1.0,tag.1.1,tag.2.0,tag.2.1,a);return}let opts:Vec<_>=p.iter().copied().filter(|&e|safe(a,e)).collect();if opts.len()<need{return}for k in 0..=opts.len()-need{let(i,j)=opts[k];a[i]^=1<<j;a[j]^=1<<i;rec(a,&opts[k+1..],need-1,tag,ct);a[i]^=1<<j;a[j]^=1<<i}}
fn main(){for l in io::stdin().lock().lines(){let v:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let z=v[0]as usize;let b=&v[1..];let vs:Vec<_>=(0..27).filter(|&i|i!=z).collect();let mut a=[0;26];let mut cross=vec![];let mut old=vec![];for i in 0..26{for j in i+1..26{let(u,w)=(vs[i],vs[j]);if b[u]>>w&1!=0{old.push((i,j));a[i]|=1<<j;a[j]|=1<<i}else if (b[z]>>u^b[z]>>w)&1!=0{cross.push((i,j))}}}let need=old.len()+2-76;let mut pairs=0;let mut ct=0;for (k,&e) in cross.iter().enumerate(){for &f in &cross[k+1..]{let mut h=a;for(i,j)in[e,f]{h[i]|=1<<j;h[j]|=1<<i}pairs+=1;
// First discharge triangle cuts. Any final cut set covers one branch; exclude earlier choices to make branches disjoint.
fn paths(h:&mut A,old:&[E],ban:&mut Vec<E>,need:usize,tag:(usize,E,E),ct:&mut u64){let mut t=None;for i in 0..26{for j in i+1..26{if h[i]>>j&1!=0{let m=h[i]&h[j];if m!=0{let k=m.trailing_zeros()as usize;t=Some([(i,j),(i.min(k),i.max(k)),(j.min(k),j.max(k))]);break}}}if t.is_some(){break}}if let Some(es)=t{if need==0{return}let n=ban.len();for e in es{if !old.contains(&e)||ban.contains(&e)||!safe(h,e){continue}let(i,j)=e;h[i]^=1<<j;h[j]^=1<<i;paths(h,old,ban,need-1,tag,ct);h[i]^=1<<j;h[j]^=1<<i;ban.push(e)}ban.truncate(n)}else{let opts:Vec<_>=old.iter().copied().filter(|&(i,j)|h[i]>>j&1!=0&&!ban.contains(&(i,j))).collect();rec(h,&opts,need,tag,ct)}}
paths(&mut h,&old,&mut vec![],need,(z,e,f),&mut ct)}}println!("done {} {} {}",z,pairs,ct)}}
